export function clientStageVariants(id){return CLIENT_STAGES.stages[id]||[];}
export function clientEnemyPack(stage){return CLIENT_STAGES.packs[stage.enemyPackName];}
// Preserve original multiplicity, spawnMode, set order and per-candidate weights.
// This returns instructions; caller owns runtime spawn timing and RNG.
export function clientSpawnInstructions(stage){
 const pack=clientEnemyPack(stage);if(!pack)return [];
 const names=['Primary','Secondary','Tertiary','Quarternary'];
 return pack.m_registDatas.map((row,index)=>{
  const direct=CLIENT_STAGES.enemies[row.m_enemyData.m_PathID];
  const field=`m_${row.m_isBoss?'boss':'normal'}${names[row.m_setType]}EnemySet${row.m_isBoss?'':'s'}`;
  const set=row.m_isBoss?pack[field]:pack[field]?.[row.m_setIndex];
  const candidates=direct?[{enemy:direct,weight:1}]:(set?.m_registDatas||[]).filter(r=>r.m_lotteryRate>0&&r.m_enemyData.m_PathID!=='0').map(r=>({enemy:CLIENT_STAGES.enemies[r.m_enemyData.m_PathID],weight:r.m_lotteryRate}));
  return {...row,index,candidates,min:row.m_min,max:row.m_max,isBoss:!!row.m_isBoss};
 });
}
